<section class="reorder-panel"><a href="<?= e(store_url($store)) ?>">← Back to store</a><p class="store-kicker">Reorder safely</p><h1>Rebuild <?= e($order['reference']) ?></h1><p>Available products are rebuilt using today’s prices and stock. Discontinued products and unavailable options are not added.</p><?php if($reorder['items']):?><div class="reorder-ready"><strong><?= e(count($reorder['items'])) ?> item types ready</strong><button class="detail-add" type="button" data-apply-reorder>Replace cart with available items</button></div><?php else:?><div class="store-empty"><h3>Nothing can be reordered</h3><p>Every item in this order is currently unavailable or needs a new option selection.</p></div><?php endif ?><?php if($reorder['skipped']):?><section class="reorder-skipped"><h2>Needs attention</h2><ul><?php foreach($reorder['skipped']as$message):?><li><?= e($message) ?></li><?php endforeach ?></ul></section><?php endif ?></section>
<script nonce="<?= e(App\Support\SecurityHeaders::nonce()) ?>" type="application/json" id="reorder-data"><?= json_encode($reorder['items'],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_SLASHES) ?></script>
